<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><style>@page{margin:24px}body{font-family:DejaVu Sans,sans-serif;color:#292524;font-size:8px}h1{margin:0;font-size:18px}.meta{margin:4px 0 14px;color:#57534e}.legend span{display:inline-block;padding:4px 7px;margin-right:5px;border-radius:8px}.shift{background:#dbeafe;color:#1e3a8a}.rest{background:#e7e5e4;color:#57534e}.approved{background:#d1fae5;color:#064e3b}.pending{background:#fef3c7;color:#78350f}table{width:100%;border-collapse:collapse;table-layout:fixed;margin-top:10px}th,td{border:1px solid #d6d3d1;padding:5px;vertical-align:top}thead th{background:#f5f5f4;text-align:center}.employee{width:110px;text-align:left}.name{font-size:9px;font-weight:bold}.muted{color:#78716c}.badge{display:block;border-radius:4px;padding:3px;margin-bottom:3px;text-align:center}.footer{margin-top:10px;color:#78716c;font-size:7px}</style></head><body><h1>Cuadrante semanal · {{ config('brand.name') }}</h1><p class="meta">Del {{ $start->format('d/m/Y') }} al {{ $end->format('d/m/Y') }}</p><div class="legend"><span class="shift">Turno</span><span class="rest">Descanso</span><span class="approved">Ausencia aprobada</span><span class="pending">Ausencia pendiente</span></div>@if($rows->isEmpty())<p>No hay empleados activos ni horarios que mostrar.</p>@else<table><thead><tr><th class="employee">Empleado</th>@foreach($days as $day)<th>{{ ucfirst($day->translatedFormat('D')) }}<br><span class="muted">{{ $day->format('d/m') }}</span></th>@endforeach</tr></thead><tbody>@foreach($rows as $row)<tr><td><span class="name">{{ $row['employee']->name }}</span><br><span class="muted">{{ $row['employee']->jobPosition?->name ?? 'Sin puesto' }}</span><br>{{ intdiv($row['weekly_minutes'],60) }}h {{ $row['weekly_minutes']%60 ? ($row['weekly_minutes']%60).'m' : '' }}</td>@foreach($row['cells'] as $cell)<td>@foreach($cell['absences'] as $absence)<span class="badge {{ $absence->status==='approved'?'approved':'pending' }}">{{ $absence->type->name }}{